/* ============================================================
   Tenlune — 레이아웃 CSS
   theme.json 으로 표현되지 않는 부분만 담습니다.

   토큰은 전부 theme.json 의 preset 변수를 다시 가리킵니다.
   색을 바꿀 일이 생기면 theme.json 만 고치면 됩니다. 이 파일에는
   색 리터럴을 새로 쓰지 않습니다. (작업물 임시 색면 두 개만 예외이며,
   실제 이미지가 들어가는 순간 삭제합니다.)

   기준: tenlune-home-final.html (Dark 최종안 · 2026-08-24)
   ============================================================ */

:root {
	--tl-bg:        var(--wp--preset--color--base);
	--tl-surface:   var(--wp--preset--color--surface);
	--tl-surface-2: var(--wp--preset--color--surface-alt);
	--tl-shot-bg:   var(--wp--preset--color--work-frame);
	--tl-line:      var(--wp--preset--color--line);
	--tl-line-2:    var(--wp--preset--color--line-strong);
	--tl-faint:     var(--wp--preset--color--text-faint);
	--tl-muted:     var(--wp--preset--color--text-muted);
	--tl-text-2:    var(--wp--preset--color--text-second);
	--tl-text:      var(--wp--preset--color--contrast);
	--tl-text-hi:   var(--wp--preset--color--contrast-hi);

	--tl-f-disp: var(--wp--preset--font-family--display);
	--tl-f-body: var(--wp--preset--font-family--body);
	--tl-f-mono: var(--wp--preset--font-family--mono);

	--tl-s-1: var(--wp--preset--spacing--10);
	--tl-s-2: var(--wp--preset--spacing--20);
	--tl-s-3: var(--wp--preset--spacing--30);
	--tl-s-4: var(--wp--preset--spacing--40);
	--tl-s-5: var(--wp--preset--spacing--50);
	--tl-s-6: var(--wp--preset--spacing--60);
	--tl-s-7: var(--wp--preset--spacing--70);
	--tl-s-8: var(--wp--preset--spacing--80);

	--tl-max: 1180px;
	--tl-pad: 1.5rem;
}
